# skillsync completion (generated by skillsync @VERSION@; do not edit)

_skillsync_subs() {
    case "$1" in
        '') _sk_reply=('link' 'skills') ;;
        'link') _sk_reply=() ;;
        'skills') _sk_reply=('add' 'list') ;;
        'skills add') _sk_reply=() ;;
        'skills list') _sk_reply=() ;;
        *) _sk_reply=() ;;
    esac
}

_skillsync_flags() {
    case "$1" in
        '') _sk_reply=('--help' '--version' '-h') ;;
        'link') _sk_reply=('--direct' '--help' '--json' '--mode' '--out-dir' '--tag' '--target-file' '-h' '-t') ;;
        'skills') _sk_reply=('--help' '-h') ;;
        'skills add') _sk_reply=('--force' '--help' '-h') ;;
        'skills list') _sk_reply=('--help' '-h') ;;
        *) _sk_reply=() ;;
    esac
}

_skillsync_kind() {
    case "$1" in
        'link|--mode') echo choices ;;
        'link|--out-dir') echo path ;;
        'link|--target-file') echo path ;;
        'link|--direct') echo value ;;
        'link|--tag') echo value ;;
        'link|-t') echo value ;;
        *) echo none ;;
    esac
}

_skillsync_choices() {
    case "$1" in
        'link|--mode') _sk_reply=('copy' 'it'\''s' 'two words') ;;
        *) _sk_reply=() ;;
    esac
}

_skillsync_pos() {
    case "$1" in
        'skills add') _sk_reply=('alpha' 'beta') ;;
        *) _sk_reply=() ;;
    esac
}

_skillsync_poskind() {
    case "$1" in
        'link') echo path ;;
        *) echo none ;;
    esac
}

_skillsync_add() {
    local s
    for s in "${_sk_reply[@]}"; do
        if [[ "$s" == "$cur"* ]]; then
            COMPREPLY+=("$s")
        fi
    done
}

_skillsync_files() {
    local IFS=$'\n'
    COMPREPLY+=($(compgen -f -- "$cur"))
}

_skillsync() {
    local cur prev node w s i kind
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev=''
    if [ "$COMP_CWORD" -gt 1 ]; then
        prev="${COMP_WORDS[COMP_CWORD-1]}"
    fi
    node=''
    COMPREPLY=()
    i=1
    while [ "$i" -lt "$COMP_CWORD" ]; do
        w="${COMP_WORDS[i]}"
        if [[ "$w" == -* ]]; then
            kind=$(_skillsync_kind "$node|$w")
            if [ "$kind" != none ]; then
                i=$((i + 1))
            fi
        else
            _skillsync_subs "$node"
            for s in "${_sk_reply[@]}"; do
                if [ "$s" = "$w" ]; then
                    node="${node:+$node }$w"
                fi
            done
        fi
        i=$((i + 1))
    done
    kind=none
    if [[ "$prev" == -* ]]; then
        kind=$(_skillsync_kind "$node|$prev")
    fi
    case "$kind" in
        path) _skillsync_files; return 0 ;;
        choices) _skillsync_choices "$node|$prev"; _skillsync_add; return 0 ;;
        value) return 0 ;;
    esac
    if [[ "$cur" == -* ]]; then
        _skillsync_flags "$node"
        _skillsync_add
        return 0
    fi
    _skillsync_subs "$node"
    _skillsync_add
    _skillsync_pos "$node"
    _skillsync_add
    if [ "$(_skillsync_poskind "$node")" = path ]; then
        _skillsync_files
    fi
    return 0
}

complete -o filenames -F _skillsync skillsync
